-- Admin-only. Every fixture and account/subscription change rolls back.
BEGIN;
CREATE TEMP TABLE commercial_rls AS SELECT oid,relrowsecurity FROM pg_class WHERE relnamespace='public'::regnamespace AND relkind='r';
DO $$
DECLARE u public.users; count_before integer; a uuid; b uuid; c uuid; caught boolean; activation text; upgrade text;
 test_auth uuid:=gen_random_uuid(); employee uuid; username text:='hr_'||replace(gen_random_uuid()::text,'-','');
 product uuid; variant uuid; sale uuid; expense uuid; req uuid:=gen_random_uuid(); report jsonb; journal jsonb; first_page jsonb; s uuid; receipt text;
BEGIN
 SELECT * INTO u FROM public.users WHERE role='owner' AND auth_id IS NOT NULL AND coalesce(is_active,true) LIMIT 1;
 IF u.id IS NULL THEN RAISE EXCEPTION 'Owner fixture missing'; END IF;
 PERFORM set_config('request.jwt.claim.sub',u.auth_id::text,true);
 SELECT count(*) INTO count_before FROM public.stores WHERE tenant_id=u.tenant_id;
 UPDATE public.tenants SET is_active=false,subscription_end_date=now()-interval '1 day' WHERE id=u.tenant_id;
 activation:='VTR-'||(count_before+2)||'-'||gen_random_uuid(); upgrade:='UPG-1-'||gen_random_uuid();
 PERFORM public.engine_activate(activation);
 IF NOT EXISTS(SELECT 1 FROM public.tenants WHERE id=u.tenant_id AND is_active AND subscription_end_date IS NULL AND branches_limit=count_before+2) THEN RAISE EXCEPTION 'Activation failed'; END IF;
 IF (public.engine_session()->'tenant'->>'branches_limit')::integer<>count_before+2 THEN RAISE EXCEPTION 'Session limit missing'; END IF;
 a:=public.engine_add_store('__commercial_A__',''); b:=public.engine_add_store('__commercial_B__','');
 caught:=false; BEGIN PERFORM public.engine_add_store('__blocked__',''); EXCEPTION WHEN OTHERS THEN caught:=true; END;
 IF NOT caught THEN RAISE EXCEPTION 'Branch limit bypass'; END IF;
 PERFORM public.engine_activate(upgrade); PERFORM public.engine_activate(upgrade);
 IF (SELECT branches_limit FROM public.tenants WHERE id=u.tenant_id)<>count_before+3 THEN RAISE EXCEPTION 'Upgrade replay duplicated capacity'; END IF;
 c:=public.engine_add_store('__commercial_C__','');
 caught:=false; BEGIN PERFORM public.engine_activate('VTR-0-invalid'); EXCEPTION WHEN OTHERS THEN caught:=true; END;
 IF NOT caught THEN RAISE EXCEPTION 'Zero limit accepted'; END IF;
 INSERT INTO auth.users(id,email,raw_app_meta_data) VALUES(test_auth,username||'@staff.vetrina.dz',jsonb_build_object('created_by_owner',u.auth_id::text));
 employee:=public.engine_register_employee_hr(test_auth,username,'employee',a,'أحمد','علي','fixed',30000);
 IF NOT EXISTS(SELECT 1 FROM public.users WHERE id=employee AND first_name='أحمد' AND last_name='علي' AND salary_type='fixed' AND salary_amount=30000 AND store_id=a AND pin_hash IS NULL) THEN RAISE EXCEPTION 'HR profile failed'; END IF;
 IF public.engine_employees(a)->0->>'first_name'<>'أحمد' THEN RAISE EXCEPTION 'HR list missing fields'; END IF;
 caught:=false; BEGIN PERFORM public.engine_register_employee_hr(test_auth,username,'employee',a,'','علي','bad',-1); EXCEPTION WHEN OTHERS THEN caught:=true; END;
 IF NOT caught THEN RAISE EXCEPTION 'Invalid HR accepted'; END IF;
 INSERT INTO public.products(tenant_id,name,base_price) VALUES(u.tenant_id,'__commercial_product__',100) RETURNING id INTO product;
 INSERT INTO public.product_variants(product_id,color,size,min_price,cost_price_avg) VALUES(product,'TEST','M',50,30) RETURNING id INTO variant;
 INSERT INTO public.inventory(store_id,variant_id,quantity) VALUES(a,variant,10);
 sale:=public.engine_sync_sale_for_staff(a,u.tenant_id,gen_random_uuid()::text,jsonb_build_array(jsonb_build_object('variant_id',variant,'quantity',2,'original_price',100,'final_price',100)),'cash',now(),u.id);
 IF (SELECT cost_at_sale FROM public.sale_items WHERE sale_id=sale)<>30 THEN RAISE EXCEPTION 'Cost snapshot missing'; END IF;
 UPDATE public.product_variants SET cost_price_avg=99 WHERE id=variant;
 expense:=public.engine_record_expense_for_staff(a,20,'test expense',null,req,u.id);
 caught:=false; BEGIN PERFORM public.engine_record_expense_for_staff(a,1,'wrong author',null,gen_random_uuid(),gen_random_uuid()); EXCEPTION WHEN OTHERS THEN caught:=true; END;
 IF NOT caught THEN RAISE EXCEPTION 'Wrong expense author accepted'; END IF;
 IF expense IS DISTINCT FROM public.engine_record_expense(a,20,'test expense',null,req) THEN RAISE EXCEPTION 'Expense retry duplicated'; END IF;
 caught:=false; BEGIN PERFORM public.engine_record_expense(a,21,'test expense',null,req); EXCEPTION WHEN OTHERS THEN caught:=true; END;
 IF NOT caught THEN RAISE EXCEPTION 'Changed expense retry accepted'; END IF;
 INSERT INTO public.shifts(store_id,user_id,expected_cash,actual_cash,status,closed_at) VALUES(a,u.id,1000,1000,'open',null) RETURNING id INTO s;
 PERFORM public.engine_employee_payment(employee,'payroll',50,'2026-11',gen_random_uuid());
 PERFORM public.engine_employee_payment(employee,'advance',10,'test',gen_random_uuid());
 report:=public.engine_accounting_commercial(a,null,now()+interval '1 day');
 IF (report->>'sales')::numeric<>200 OR (report->>'costOfGoods')::numeric<>60 OR (report->>'expenses')::numeric<>20 OR (report->>'netProfit')::numeric<>60 OR (report->>'estimatedCostItems')::integer<>0 THEN RAISE EXCEPTION 'Commercial totals failed: %',report; END IF;
 IF (public.engine_accounting_commercial(b,null,now()+interval '1 day')->>'sales')::integer<>0 THEN RAISE EXCEPTION 'Cross branch leakage'; END IF;
 journal:=public.engine_journal(a,null,now()+interval '1 day',0);
 IF jsonb_array_length(journal->'rows')<>4 THEN RAISE EXCEPTION 'Journal types missing: %',journal; END IF;
 INSERT INTO public.expenses(store_id,amount,description,created_by,status) SELECT a,1,'page test',u.id,'approved' FROM generate_series(1,55);
 first_page:=public.engine_journal(a,null,now()+interval '1 day',0); journal:=public.engine_journal(a,null,now()+interval '1 day',50);
 IF jsonb_array_length(first_page->'rows')<>50 OR NOT (first_page->>'hasMore')::boolean OR jsonb_array_length(journal->'rows')<>9 OR (journal->>'hasMore')::boolean THEN RAISE EXCEPTION 'Journal pagination failed'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(first_page->'rows') x JOIN jsonb_array_elements(journal->'rows') y ON x->>'id'=y->>'id' AND x->>'type'=y->>'type') THEN RAISE EXCEPTION 'Pagination duplicates'; END IF;
 receipt:=u.tenant_id||'/'||a||'/'||u.auth_id||'/'||gen_random_uuid()||'.pdf';
 INSERT INTO storage.objects(bucket_id,name) VALUES('expense-receipts',receipt);
 PERFORM public.engine_record_expense(a,1,'with receipt',receipt,gen_random_uuid());
 IF public.engine_receipt_unattached(receipt) THEN RAISE EXCEPTION 'Attached receipt deletable'; END IF;
 UPDATE public.users SET role='employee',store_id=a WHERE id=u.id;
 PERFORM public.engine_record_expense(a,1,'employee permitted',null,gen_random_uuid());
 IF NOT public.engine_receipt_access(receipt,false) OR public.engine_receipt_access(u.tenant_id||'/'||b||'/'||u.auth_id||'/fake.pdf',true) OR public.engine_receipt_access(gen_random_uuid()||'/'||a||'/'||u.auth_id||'/fake.pdf',false) THEN RAISE EXCEPTION 'Receipt scope failed'; END IF;
 caught:=false; BEGIN PERFORM public.engine_record_expense(b,1,'denied',null,gen_random_uuid()); EXCEPTION WHEN OTHERS THEN caught:=true; END;
 IF NOT caught THEN RAISE EXCEPTION 'Employee cross-store expense accepted'; END IF;
 caught:=false; BEGIN PERFORM public.engine_journal(a,null,now()+interval '1 day',0); EXCEPTION WHEN OTHERS THEN caught:=true; END;
 IF NOT caught THEN RAISE EXCEPTION 'Employee journal accepted'; END IF;
 caught:=false; BEGIN PERFORM public.engine_accounting_commercial(a,null,now()+interval '1 day'); EXCEPTION WHEN OTHERS THEN caught:=true; END;
 IF NOT caught THEN RAISE EXCEPTION 'Employee accounting accepted'; END IF;
 caught:=false; BEGIN PERFORM public.engine_activate('UPG-5-denied'); EXCEPTION WHEN OTHERS THEN caught:=true; END;
 IF NOT caught THEN RAISE EXCEPTION 'Employee upgrade accepted'; END IF;
 IF EXISTS(SELECT 1 FROM commercial_rls before JOIN pg_class after ON after.oid=before.oid WHERE after.relrowsecurity<>before.relrowsecurity) THEN RAISE EXCEPTION 'RLS flags changed'; END IF;
END $$;
ROLLBACK;
